+        assert_eq!(report["runs"][0]["evals"][0]["reason"], "last { brace");
+    }
+    let (_, output) = journey(
+        json!({"status":"ok","text":"{\"value\":2} then {\"value\":8,\"reason\":\"revised\"} trailing prose"}),
+        true,
+        0,
+    );
+    assert_eq!(output.status.code(), Some(0));
+}
